using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evaluation;

public class EvaluationTests : IAsyncLifetime
{
    private static readonly ChatConfiguration s_chatConfiguration = new()
    {
        ModelId = "gpt-4o-mini",
    };

    private static readonly ReportingConfiguration s_reportingConfiguration =
        CreateReportingConfiguration();

    private ScenarioRun? _scenarioRun;

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        var storage = new DiskBasedReportingStorage(
            storageRootPath: Path.Combine(
                Directory.GetCurrentDirectory(), "evaluation-results"));

        return new ReportingConfiguration(evaluators, storage);
    }

    public async Task InitializeAsync()
    {
        _scenarioRun = await s_reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(EvaluationTests),
            chatConfiguration: s_chatConfiguration);
    }

    public async Task DisposeAsync()
    {
        if (_scenarioRun is not null)
        {
            await _scenarioRun.DisposeAsync();
        }
    }

    [Fact]
    public async Task Chat_Response_Is_Coherent_And_Relevant()
    {
        // Arrange
        var scenarios = ScenarioLoader.LoadScenarios("Scenarios/chat_scenarios.json");
        var chatClient = GetChatClient();

        foreach (var scenario in scenarios)
        {
            // Act
            var messages = new List<ChatMessage>
            {
                new(ChatRole.User, scenario.UserMessage),
            };

            var response = await chatClient.GetResponseAsync(messages);
            messages.Add(response.Message);

            // Evaluate
            await _scenarioRun!.EvaluateAsync(messages, additionalContext:
                scenario.ExpectedContext is not null
                    ? [new EvaluationContext(scenario.ExpectedContext)]
                    : null);
        }
    }

    [Fact]
    public async Task Chat_Handles_Multi_Turn_Conversation()
    {
        // Arrange
        var scenarios = ScenarioLoader.LoadScenarios("Scenarios/multi_turn_scenarios.json");
        var chatClient = GetChatClient();

        foreach (var scenario in scenarios)
        {
            var messages = new List<ChatMessage>();

            foreach (var turn in scenario.Turns)
            {
                messages.Add(new ChatMessage(ChatRole.User, turn));
                var response = await chatClient.GetResponseAsync(messages);
                messages.Add(response.Message);
            }

            // Evaluate the full conversation
            await _scenarioRun!.EvaluateAsync(messages);
        }
    }

    private static IChatClient GetChatClient()
    {
        // In integration tests this would come from the Aspire app host.
        // For standalone evaluation, configure via environment variables.
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException(
                "Set AZURE_OPENAI_ENDPOINT environment variable.");

        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
            ?? throw new InvalidOperationException(
                "Set AZURE_OPENAI_API_KEY environment variable.");

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(apiKey))
            .GetChatClient(s_chatConfiguration.ModelId)
            .AsIChatClient();
    }
}

using System.Text.Json;

namespace MyApp.Evaluation;

public static class ScenarioLoader
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNameCaseInsensitive = true,
    };

    public static IReadOnlyList<ChatScenario> LoadScenarios(string path)
    {
        var json = File.ReadAllText(path);
        return JsonSerializer.Deserialize<List<ChatScenario>>(json, s_options)
            ?? throw new InvalidOperationException($"Failed to load scenarios from {path}");
    }
}

public record ChatScenario
{
    public string Name { get; init; } = string.Empty;
    public string UserMessage { get; init; } = string.Empty;
    public string? ExpectedContext { get; init; }
    public List<string> Turns { get; init; } = [];
}

[
  {
    "name": "greeting",
    "userMessage": "Hello, can you help me with a quick question?",
    "expectedContext": "The assistant should respond politely and offer help."
  },
  {
    "name": "factual_question",
    "userMessage": "What is the capital of France?",
    "expectedContext": "The capital of France is Paris."
  },
  {
    "name": "summarization",
    "userMessage": "Summarize the benefits of cloud computing in two sentences.",
    "expectedContext": "Cloud computing provides scalable resources on demand and reduces infrastructure costs."
  }
]

[
  {
    "name": "follow_up_question",
    "turns": [
      "What programming language is C# most similar to?",
      "Can you give me an example of a feature they share?"
    ]
  },
  {
    "name": "context_retention",
    "turns": [
      "My favorite color is blue.",
      "What did I just tell you my favorite color is?"
    ]
  }
]

